import os
import json
import uuid
import time
import httpx
from pathlib import Path
from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, StreamingResponse, JSONResponse

app = FastAPI()

ORCAROUTER_API_KEY = os.environ.get("ORCAROUTER_API_KEY", "")
BASE_URL = ""
MODEL = "anthropic/claude-opus-4.8"
MAX_TOKENS = 128000

sessions: dict = {}

BASE_DIR = Path(__file__).parent


@app.get("/")
async def serve_index():
    content = (BASE_DIR / "index.html").read_text(encoding="utf-8")
    return HTMLResponse(content=content)


@app.post("/api/chat")
async def chat(request: Request):
    try:
        data = await request.json()
    except Exception:
        return JSONResponse({"error": "Invalid JSON"}, status_code=400)

    message = (data.get("message") or "").strip()
    session_id = data.get("session_id") or str(uuid.uuid4())
    images = data.get("images") or []

    if not message and not images:
        return JSONResponse({"error": "Empty message"}, status_code=400)

    if session_id not in sessions:
        sessions[session_id] = {
            "messages": [],
            "updated_at": int(time.time() * 1000),
            "preview": "",
        }

    # Build user message content (OpenAI format)
    if images:
        content: list = []
        for img in images:
            if isinstance(img, dict) and img.get("data") and img.get("media_type"):
                data_url = f"data:{img['media_type']};base64,{img['data']}"
                content.append({"type": "image_url", "image_url": {"url": data_url}})
        if message:
            content.append({"type": "text", "text": message})
        user_msg = {"role": "user", "content": content}
    else:
        user_msg = {"role": "user", "content": message}

    sessions[session_id]["messages"].append(user_msg)
    sessions[session_id]["preview"] = message[:68] if message else "[Kép]"
    sessions[session_id]["updated_at"] = int(time.time() * 1000)

    async def generate():
        yield f"data: {json.dumps({'type': 'session', 'session_id': session_id})}\n\n"

        # Build API messages (text-only for history to avoid large payloads)
        api_messages = []
        for m in sessions[session_id]["messages"]:
            role = m.get("role", "")
            mc = m.get("content", "")
            if isinstance(mc, str):
                api_messages.append({"role": role, "content": mc})
            elif isinstance(mc, list):
                api_messages.append({"role": role, "content": mc})

        payload = {
            "model": MODEL,
            "max_tokens": MAX_TOKENS,
            "stream": True,
            "messages": api_messages,
        }

        full_response = ""

        try:
            async with httpx.AsyncClient(timeout=None) as client:
                async with client.stream(
                    "POST",
                    f"{BASE_URL}/chat/completions",
                    headers={
                        "Authorization": f"Bearer {ORCAROUTER_API_KEY}",
                        "Content-Type": "application/json",
                    },
                    json=payload,
                ) as response:
                    if response.status_code != 200:
                        error_body = await response.aread()
                        try:
                            err = json.loads(error_body)
                            msg = (
                                err.get("error", {}).get("message", "")
                                or err.get("message", "")
                                or str(error_body[:300])
                            )
                        except Exception:
                            msg = error_body[:300].decode(errors="replace")
                        yield f"data: {json.dumps({'type': 'error', 'message': f'API hiba {response.status_code}: {msg}'})}\n\n"
                        return

                    async for line in response.aiter_lines():
                        if not line:
                            continue
                        if not line.startswith("data: "):
                            continue
                        raw = line[6:]
                        if raw.strip() == "[DONE]":
                            break
                        try:
                            ev = json.loads(raw)
                        except Exception:
                            continue

                        choices = ev.get("choices") or []
                        if not choices:
                            continue
                        delta = choices[0].get("delta") or {}
                        text = delta.get("content") or ""
                        if text:
                            full_response += text
                            yield f"data: {json.dumps({'type': 'content', 'text': text})}\n\n"

        except Exception as exc:
            yield f"data: {json.dumps({'type': 'error', 'message': str(exc)[:500]})}\n\n"
            return

        if full_response:
            sessions[session_id]["messages"].append({
                "role": "assistant",
                "content": full_response,
            })
            sessions[session_id]["updated_at"] = int(time.time() * 1000)

    return StreamingResponse(
        generate(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )


@app.get("/api/sessions")
async def list_sessions():
    result = []
    for sid, data in sessions.items():
        msgs = data.get("messages", [])
        result.append({
            "session_id": sid,
            "preview": data.get("preview") or "Chat",
            "count": len(msgs),
            "updated_at": data.get("updated_at", 0),
        })
    result.sort(key=lambda x: x["updated_at"], reverse=True)
    return {"sessions": result}


@app.get("/api/session/{session_id}")
async def get_session(session_id: str):
    if session_id not in sessions:
        return JSONResponse({"error": "Not found"}, status_code=404)

    msgs = sessions[session_id].get("messages", [])
    formatted = []
    for m in msgs:
        role = m.get("role", "")
        content = m.get("content", "")
        if isinstance(content, str):
            formatted.append({"role": role, "content": content})
        elif isinstance(content, list):
            text_parts = []
            has_image = False
            for item in content:
                if isinstance(item, dict):
                    if item.get("type") == "text":
                        text_parts.append(item["text"])
                    elif item.get("type") == "image_url":
                        has_image = True
            formatted.append({
                "role": role,
                "content": "\n".join(text_parts),
                "has_image": has_image,
            })

    return {"messages": formatted}


@app.delete("/api/session/{session_id}")
async def delete_session(session_id: str):
    sessions.pop(session_id, None)
    return {"ok": True}


if __name__ == "__main__":
    import uvicorn
    port = int(os.environ.get("PORT", 8000))
    uvicorn.run(app, host="0.0.0.0", port=port, log_level="info")



